"""DRILL: Union-Find / DSU. Target: <= 3 minutes."""
class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return True

d = DSU(5)
assert d.union(0,1) is True
assert d.union(1,2) is True
assert d.find(0) == d.find(2)
assert d.union(0,2) is False
assert d.find(3) != d.find(0)
print("PASS")

"""DRILL: Graph BFS adjacency list. Target: <= 90 seconds."""
from collections import deque

def bfs_distances(graph, start):
    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in graph.get(u, []):
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

g = {0:[1,2], 1:[3], 2:[3], 3:[], 4:[]}
assert bfs_distances(g, 0) == {0:0,1:1,2:1,3:2}
assert bfs_distances(g, 4) == {4:0}
print("PASS")

"""DRILL: Graph DFS adjacency list. Target: <= 90 seconds."""
def dfs(graph, start):
    visited = set()
    stack = [start]
    while stack:
        u = stack.pop()
        if u in visited:
            continue
        visited.add(u)
        for v in graph.get(u, []):
            if v not in visited:
                stack.append(v)
    return visited

g = {0:[1,2], 1:[2], 2:[3], 3:[], 4:[]}
assert dfs(g, 0) == {0,1,2,3}
assert dfs(g, 4) == {4}
print("PASS")

"""DRILL: Grid DFS + visited. Target: <= 2 minutes."""
def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if grid[r][c] != "1" or visited[r][c]:
            return
        visited[r][c] = True
        dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1" and not visited[r][c]:
                dfs(r,c)
                count += 1
    return count

assert count_islands([
    ["1","1","0"],
    ["0","1","0"],
    ["1","0","1"],
]) == 3
assert count_islands([]) == 0
print("PASS")

"""DRILL: Heap / top-K. Target: <= 2 minutes."""
import heapq

def k_largest(nums, k):
    if k <= 0:
        return []
    heap = []
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)
    return sorted(heap, reverse=True)

assert k_largest([3,2,1,5,6,4], 2) == [6,5]
assert k_largest([1], 1) == [1]
assert k_largest([4,4,2,9], 3) == [9,4,4]
print("PASS")

"""DRILL: Iterative tree DFS with stack. Target: <= 2 minutes."""
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def preorder(root):
    if not root:
        return []
    stack = [root]
    res = []
    while stack:
        node = stack.pop()
        res.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return res

root = Node(1, Node(2, Node(4), Node(5)), Node(3))
assert preorder(root) == [1,2,4,5,3]
assert preorder(None) == []
print("PASS")

"""DRILL: Tree level-order BFS. Target: <= 2 minutes."""
from collections import deque

class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def level_order(root):
    if not root:
        return []
    q = deque([root])
    res = []
    while q:
        level = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        res.append(level)
    return res

root = Node(1, Node(2, Node(4)), Node(3))
assert level_order(root) == [[1],[2,3],[4]]
assert level_order(None) == []
print("PASS")

"""DRILL: Trie insert/search/prefix. Target: <= 4 minutes."""
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

    def starts_with(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return True

t = Trie()
t.insert("apple")
assert t.search("apple") is True
assert t.search("app") is False
assert t.starts_with("app") is True
t.insert("app")
assert t.search("app") is True
print("PASS")

"""DRILL: Opposite-direction two pointers. Target: <= 90 seconds."""
def pair_sum_sorted(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s == target:
            return (lo, hi)
        elif s < target:
            lo += 1
        else:
            hi -= 1
    return None

assert pair_sum_sorted([1,2,4,7,11], 9) == (1,3)
assert pair_sum_sorted([1,2], 10) is None
assert pair_sum_sorted([-3,-1,2,5], 1) == (1,2)
print("PASS")
